// MoneybirdDataInput Complete Moneybird sandbox data structure - API format
//
// Note: Objects are created in dependency order:
// 1. Ledger accounts (no dependencies)
// 2. Contacts (no dependencies)
// 3. Products (no dependencies, but needs tax rates from system)
// 4. Projects (no dependencies)
// 5. Time entries (linked to projects and contacts)
// 6. Sales invoices (linked to contacts)
type MoneybirdDataInput struct {
	// Contacts List of contacts to create
	Contacts *[]MoneybirdContact `json:"contacts,omitempty"`

	// LedgerAccounts List of ledger accounts to create
	LedgerAccounts *[]MoneybirdLedgerAccount `json:"ledger_accounts,omitempty"`

	// Products List of products to create
	Products *[]MoneybirdProduct `json:"products,omitempty"`

	// Projects List of projects to create
	Projects *[]MoneybirdProject `json:"projects,omitempty"`

	// SalesInvoices List of sales invoices to create
	SalesInvoices *[]MoneybirdSalesInvoice `json:"sales_invoices,omitempty"`

	// TimeEntries List of time entries to create
	TimeEntries *[]MoneybirdTimeEntry `json:"time_entries,omitempty"`
}

// MoneybirdDataOutput Complete Moneybird sandbox data structure - API format
//
// Note: Objects are created in dependency order:
// 1. Ledger accounts (no dependencies)
// 2. Contacts (no dependencies)
// 3. Products (no dependencies, but needs tax rates from system)
// 4. Projects (no dependencies)
// 5. Time entries (linked to projects and contacts)
// 6. Sales invoices (linked to contacts)
type MoneybirdDataOutput struct {
	// Contacts List of contacts to create
	Contacts *[]MoneybirdContact `json:"contacts,omitempty"`

	// LedgerAccounts List of ledger accounts to create
	LedgerAccounts *[]MoneybirdLedgerAccount `json:"ledger_accounts,omitempty"`

	// Products List of products to create
	Products *[]MoneybirdProduct `json:"products,omitempty"`

	// Projects List of projects to create
	Projects *[]MoneybirdProject `json:"projects,omitempty"`

	// SalesInvoices List of sales invoices to create
	SalesInvoices *[]MoneybirdSalesInvoice `json:"sales_invoices,omitempty"`

	// TimeEntries List of time entries to create
	TimeEntries *[]MoneybirdTimeEntry `json:"time_entries,omitempty"`
}

